<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { api, type LotteryActivity, type LotteryPrize, type PointAccount, type PointOrder, type PointProduct, type PointsDashboard, type LotteryWin, type RobloxMusicSubmission } from '@/api'

type Tab = 'dashboard' | 'products' | 'activities' | 'orders' | 'wins' | 'accounts' | 'music'
const tab = ref<Tab>('dashboard')
const products = ref<PointProduct[]>([]); const activities = ref<LotteryActivity[]>([]); const orders = ref<PointOrder[]>([]); const accounts = ref<PointAccount[]>([]); const wins = ref<LotteryWin[]>([]); const musicSubmissions = ref<RobloxMusicSubmission[]>([]); const dashboard = ref<PointsDashboard | null>(null)
const notice = ref(''); const busy = ref(false); const editingProduct = ref<PointProduct | null>(null); const editingActivity = ref<LotteryActivity | null>(null); const editingPrize = ref<LotteryPrize | null>(null)
const filters = reactive({ status: '', product_id: '', user_id: '', start: '', end: '' })
const productForm = reactive<any>({ name: '', image_url: '', points_required: 100, shipping_points: 0, stock: 1, physical: false, description: '', status: 'draft', sort_order: 0 })
const activityForm = reactive<any>({ name: '', cover_url: '', description: '', style: 'wheel', cost_points: 0, daily_limit: 0, total_limit: 0, daily_free_attempts: 0, starts_at: '', ends_at: '', status: 'draft', sort_order: 0 })
const prizeForm = reactive<any>({ activity_id: 0, name: '', image_url: '', probability_bp: 0, stock: 1, prize_type: 'points', bound_id: 0, config_json: '{"points":100}', physical: false, sort_order: 0 })
const shipping = reactive({ carrier: '', tracking_no: '' })

function resetProduct(item?: PointProduct) { editingProduct.value = item || null; Object.assign(productForm, item || { name: '', image_url: '', points_required: 100, shipping_points: 0, stock: 1, physical: false, description: '', status: 'draft', sort_order: 0 }) }
function resetActivity(item?: LotteryActivity) { editingActivity.value = item || null; Object.assign(activityForm, item ? { ...item, starts_at: item.starts_at.slice(0, 16), ends_at: item.ends_at.slice(0, 16) } : { name: '', cover_url: '', description: '', style: 'wheel', cost_points: 0, daily_limit: 0, total_limit: 0, daily_free_attempts: 0, starts_at: '', ends_at: '', status: 'draft', sort_order: 0 }) }
function resetPrize(activity: LotteryActivity, item?: LotteryPrize) { editingPrize.value = item || null; Object.assign(prizeForm, item ? { ...item } : { activity_id: activity.id, name: '', image_url: '', probability_bp: 0, stock: 1, prize_type: 'points', bound_id: 0, config_json: '{"points":100}', physical: false, sort_order: 0 }) }
async function load() { const requests = [api.get('/admin/points/products'), api.get('/admin/lottery/activities'), api.get('/admin/points/orders'), api.get('/admin/points/accounts'), api.get('/admin/lottery/wins'), api.get('/admin/points/dashboard'), api.get('/admin/roblox/music', { params: { status: 'pending' } })]; const [p, a, o, u, w, d, m] = await Promise.all(requests); products.value = p.data.data; activities.value = a.data.data; orders.value = o.data.data; accounts.value = u.data.data; wins.value = w.data.data; dashboard.value = d.data.data; musicSubmissions.value = m.data.data }
async function reloadOrders() { const query = new URLSearchParams(Object.entries(filters).filter(([, value]) => value) as [string, string][]).toString(); orders.value = (await api.get(`/admin/points/orders?${query}`)).data.data }
async function saveProduct() { busy.value = true; try { const id = editingProduct.value?.id; await (id ? api.put(`/admin/points/products/${id}`, productForm) : api.post('/admin/points/products', productForm)); notice.value = '商品已保存'; resetProduct(); await load() } catch (error: any) { notice.value = error?.response?.data?.error?.message || '商品保存失败' } finally { busy.value = false } }
async function saveActivity() { busy.value = true; try { const id = editingActivity.value?.id; const payload = { ...activityForm, starts_at: new Date(activityForm.starts_at).toISOString(), ends_at: new Date(activityForm.ends_at).toISOString() }; await (id ? api.put(`/admin/lottery/activities/${id}`, payload) : api.post('/admin/lottery/activities', payload)); notice.value = '活动已保存'; resetActivity(); await load() } catch (error: any) { notice.value = error?.response?.data?.error?.message || '活动保存失败' } finally { busy.value = false } }
async function savePrize() { busy.value = true; try { const id = editingPrize.value?.id; await (id ? api.put(`/admin/lottery/activities/${prizeForm.activity_id}/prizes/${id}`, prizeForm) : api.post(`/admin/lottery/activities/${prizeForm.activity_id}/prizes`, prizeForm)); notice.value = '奖品已保存'; editingPrize.value = null; await load() } catch (error: any) { notice.value = error?.response?.data?.error?.message || '奖品保存失败' } finally { busy.value = false } }
async function ship(order: PointOrder) { busy.value = true; try { await api.patch(`/admin/points/orders/${order.id}/ship`, shipping); shipping.carrier = ''; shipping.tracking_no = ''; notice.value = '订单已发货'; await load() } catch (error: any) { notice.value = error?.response?.data?.error?.message || '发货失败' } finally { busy.value = false } }
async function deliver(win: LotteryWin) { try { await api.patch(`/admin/lottery/wins/${win.id}/deliver`); notice.value = '奖品已标记发放'; await load() } catch (error: any) { notice.value = error?.response?.data?.error?.message || '发放失败' } }
async function reviewMusic(item: RobloxMusicSubmission, status: 'approved' | 'rejected') { let note = ''; if (status === 'approved') { if (!window.confirm(`确定通过“${item.name}”并加入音乐库吗？`)) return } else { const value = window.prompt(`请输入驳回“${item.name}”的原因`); if (value === null) return; note = value.trim(); if (!note) { notice.value = '请填写驳回原因'; return } } busy.value = true; try { await api.patch(`/admin/roblox/music/${item.id}`, { status, note }); notice.value = status === 'approved' ? '音乐投稿已通过' : '音乐投稿已驳回'; await load() } catch (error: any) { notice.value = error?.response?.data?.error?.message || '音乐投稿审核失败' } finally { busy.value = false } }
onMounted(async () => { await load(); resetProduct(); resetActivity() })
</script>

<template>
  <section class="rf-page admin-points"><header class="rf-page-header"><div class="rf-page-heading"><h1>积分与活动</h1><p>集中管理积分商品、抽奖活动、订单履约与奖品发放。</p></div></header>
    <p v-if="notice" class="admin-notice" role="status">{{ notice }}</p>
    <nav class="admin-tabs"><button v-for="item in [['dashboard','概览'],['products','商品'],['activities','活动'],['orders','订单'],['wins','中奖'],['accounts','积分账户'],['music','音乐投稿']]" :key="item[0]" :class="{ active: tab === item[0] }" @click="tab = item[0] as Tab">{{ item[1] }}</button></nav>
    <section v-if="tab === 'dashboard' && dashboard" class="dashboard"><div class="metric-grid"><article><span>积分账户</span><strong>{{ dashboard.account_count }}</strong></article><article><span>积分总余额</span><strong>{{ dashboard.total_balance }}</strong></article><article><span>兑换订单</span><strong>{{ dashboard.order_count }}</strong><small>待处理 {{ dashboard.pending_orders }}</small></article><article><span>抽奖次数</span><strong>{{ dashboard.draw_count }}</strong><small>中奖 {{ dashboard.win_count }}</small></article><article><span>待发放</span><strong>{{ dashboard.pending_wins }}</strong></article></div><div class="stats-table"><div class="stats-head"><span>活动</span><span>参与人数</span><span>抽奖次数</span><span>中奖率</span><span>消耗积分</span></div><div v-for="item in dashboard.activities" :key="item.activity_id" class="stats-row"><strong>{{ item.activity_name }}</strong><span>{{ item.unique_users }}</span><span>{{ item.draw_count }}</span><span>{{ (item.win_rate_bp / 100).toFixed(2) }}%</span><span>{{ item.points_spent }}</span></div></div></section>
    <section v-else-if="tab === 'products'" class="workspace"><form class="editor" @submit.prevent="saveProduct"><h2>{{ editingProduct ? '编辑商品' : '新增商品' }}</h2><div class="form-grid"><label>商品名称<input v-model.trim="productForm.name" required maxlength="120" /></label><label>图片 URL<input v-model.trim="productForm.image_url" /></label><label>所需积分<input v-model.number="productForm.points_required" type="number" min="1" required /></label><label>邮费积分<input v-model.number="productForm.shipping_points" type="number" min="0" /></label><label>库存<input v-model.number="productForm.stock" type="number" min="0" /></label><label>排序<input v-model.number="productForm.sort_order" type="number" /></label><label>状态<select v-model="productForm.status"><option value="draft">草稿</option><option value="on_sale">上架</option><option value="off_sale">下架</option></select></label><label class="check"><input v-model="productForm.physical" type="checkbox" /> 实物商品</label><label class="full">商品描述<textarea v-model="productForm.description" rows="3" /></label></div><div class="editor-actions"><button type="submit" class="rf-primary-button" :disabled="busy">保存商品</button><button type="button" class="rf-text-button" @click="resetProduct()">清空</button></div></form><div class="admin-table"><div v-for="item in products" :key="item.id" class="admin-row"><div><strong>{{ item.name }}</strong><small>{{ item.points_required + item.shipping_points }} 积分 · 库存 {{ item.stock }}</small></div><span>{{ item.status }}</span><button class="rf-text-button" @click="resetProduct(item)">编辑</button></div></div></section>
    <section v-else-if="tab === 'activities'" class="workspace"><form class="editor" @submit.prevent="saveActivity"><h2>{{ editingActivity ? '编辑活动' : '新增活动' }}</h2><div class="form-grid"><label>活动名称<input v-model.trim="activityForm.name" required /></label><label>封面图<input v-model.trim="activityForm.cover_url" /></label><label>玩法<select v-model="activityForm.style"><option value="wheel">转盘</option><option value="scratch">刮刮乐</option></select></label><label>单次消耗<input v-model.number="activityForm.cost_points" type="number" min="0" /></label><label>每日限制<input v-model.number="activityForm.daily_limit" type="number" min="0" /></label><label>活动总限制<input v-model.number="activityForm.total_limit" type="number" min="0" /></label><label>每日免费次数<input v-model.number="activityForm.daily_free_attempts" type="number" min="0" /></label><label>状态<select v-model="activityForm.status"><option value="draft">草稿</option><option value="on_sale">上架</option><option value="off_sale">下架</option></select></label><label>开始时间<input v-model="activityForm.starts_at" type="datetime-local" required /></label><label>结束时间<input v-model="activityForm.ends_at" type="datetime-local" required /></label><label class="full">活动说明<textarea v-model="activityForm.description" rows="3" /></label></div><div class="editor-actions"><button type="submit" class="rf-primary-button" :disabled="busy">保存活动</button><button type="button" class="rf-text-button" @click="resetActivity()">清空</button></div></form><div class="activity-list"><article v-for="item in activities" :key="item.id" class="activity-card"><div><strong>{{ item.name }}</strong><small>{{ item.style === 'scratch' ? '刮刮乐' : '转盘' }} · {{ item.cost_points }} 积分/次</small></div><div class="activity-card-actions"><button class="rf-text-button" @click="resetActivity(item)">编辑活动</button><button class="rf-text-button" @click="resetPrize(item)">新增奖品</button></div><div class="prize-mini" v-for="prize in item.prizes" :key="prize.id"><span>{{ prize.name }} · {{ prize.prize_type }}</span><small>{{ (prize.probability_bp / 100).toFixed(2) }}% · 库存 {{ prize.stock }}</small><button class="rf-text-button" @click="resetPrize(item, prize)">编辑</button></div></article></div><form v-if="prizeForm.activity_id" class="editor prize-editor" @submit.prevent="savePrize"><h2>{{ editingPrize ? '编辑奖品' : '新增奖品' }}</h2><div class="form-grid"><label>奖品名称<input v-model.trim="prizeForm.name" required /></label><label>图片 URL<input v-model.trim="prizeForm.image_url" /></label><label>中奖概率（万分比）<input v-model.number="prizeForm.probability_bp" type="number" min="0" max="10000" /></label><label>库存<input v-model.number="prizeForm.stock" type="number" min="0" /></label><label>奖品类型<select v-model="prizeForm.prize_type"><option value="points">积分</option><option value="membership">会员</option><option value="wallet">钱包余额</option><option value="physical">实物</option><option value="custom">自定义</option></select></label><label>绑定 ID<input v-model.number="prizeForm.bound_id" type="number" min="0" /></label><label class="full">配置 JSON<textarea v-model="prizeForm.config_json" rows="3" required /></label></div><button class="rf-primary-button" type="submit" :disabled="busy">保存奖品</button></form></section>
    <section v-else-if="tab === 'orders'" class="workspace"><div class="filters"><select v-model="filters.status" @change="reloadOrders"><option value="">全部状态</option><option value="pending">待处理</option><option value="shipped">已发货</option><option value="completed">已完成</option></select><input v-model="filters.product_id" placeholder="商品 ID" @change="reloadOrders" /><input v-model="filters.user_id" placeholder="用户 ID" @change="reloadOrders" /><input v-model="filters.start" type="date" @change="reloadOrders" /><input v-model="filters.end" type="date" @change="reloadOrders" /></div><div class="admin-table"><div v-for="item in orders" :key="item.id" class="admin-row order-row"><div><strong>{{ item.order_no }} · {{ item.product_name }}</strong><small>{{ item.user_name }} · {{ item.points_spent + item.shipping_points }} 积分 · {{ item.status }}</small><small v-if="item.carrier">{{ item.carrier }} {{ item.tracking_no }}</small></div><div v-if="item.status === 'pending' && item.physical" class="ship-fields"><input v-model="shipping.carrier" placeholder="物流公司" /><input v-model="shipping.tracking_no" placeholder="物流单号" /><button class="rf-text-button" @click="ship(item)">发货</button></div></div></div></section>
    <section v-else-if="tab === 'wins'" class="workspace"><div class="admin-table"><div v-for="item in wins" :key="item.id" class="admin-row"><div><strong>{{ item.prize_name }}</strong><small>{{ item.user_name }} · {{ item.activity_name }} · {{ item.status }}</small></div><button v-if="item.prize_type === 'custom' && item.status === 'pending'" class="rf-text-button" @click="deliver(item)">标记已发放</button></div></div></section>
    <section v-else-if="tab === 'music'" class="admin-table music-review"><div v-for="item in musicSubmissions" :key="item.id" class="admin-row"><div class="music-review-main"><img v-if="item.image_url" :src="item.image_url" alt="" /><div><strong>{{ item.name }}</strong><small>Roblox ID {{ item.asset_id }} · 投稿人 {{ item.user_name }}</small></div></div><div class="music-review-actions"><button class="rf-text-button" :disabled="busy" @click="reviewMusic(item, 'approved')">通过</button><button class="rf-text-button danger" :disabled="busy" @click="reviewMusic(item, 'rejected')">驳回</button></div></div><nut-empty v-if="!musicSubmissions.length" description="暂无待审核音乐投稿" /></section>
    <section v-else class="admin-table accounts"><div v-for="item in accounts" :key="item.user_id" class="admin-row"><div><strong>{{ item.user_name }}</strong><small>累计获得 {{ item.total_earned }} · 消耗 {{ item.total_spent }}</small></div><b>{{ item.balance }} 积分</b></div></section>
  </section>
</template>

<style scoped>
.admin-points{padding-bottom:48px}.admin-notice{margin:0;padding:12px 20px;color:var(--primary);background:color-mix(in srgb,var(--primary) 9%,var(--rf-bg));font-size:13px}.admin-tabs{display:flex;gap:6px;padding:16px 20px;border-bottom:1px solid var(--rf-line);overflow:auto}.admin-tabs button{padding:9px 14px;border-radius:999px;color:var(--rf-muted);background:var(--rf-bg-subtle);white-space:nowrap}.admin-tabs button.active{color:#fff;background:var(--primary);font-weight:700}.workspace{display:grid;grid-template-columns:minmax(300px,420px) minmax(0,1fr);gap:24px;padding:20px}.editor{align-self:start;padding:18px;border:1px solid var(--rf-line);border-radius:8px;background:var(--rf-bg-subtle)}.editor h2{margin:0 0 16px;font-size:18px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.form-grid label{display:flex;flex-direction:column;gap:5px;color:var(--rf-muted);font-size:12px}.form-grid input,.form-grid select,.form-grid textarea,.filters input,.filters select,.ship-fields input{width:100%;padding:9px;border:1px solid var(--rf-line);border-radius:6px;color:var(--rf-text);background:var(--rf-bg)}.form-grid .full{grid-column:1/-1}.form-grid .check{display:flex;justify-content:center;flex-direction:row;align-items:center}.editor-actions{display:flex;gap:12px;margin-top:16px}.admin-table{padding:0 20px}.admin-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:center;gap:16px;min-height:68px;border-bottom:1px solid var(--rf-line)}.admin-row>div{display:flex;min-width:0;flex-direction:column;gap:4px}.admin-row small,.admin-row>span{color:var(--rf-muted);font-size:12px}.admin-row strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.activity-list{display:flex;flex-direction:column;gap:10px}.activity-card{padding:14px;border:1px solid var(--rf-line);border-radius:8px}.activity-card>div:first-child{display:flex;justify-content:space-between;gap:12px}.activity-card small{display:block;color:var(--rf-muted);font-size:12px}.activity-card-actions{display:flex;gap:8px;margin:10px 0}.prize-mini{display:grid;grid-template-columns:1fr auto auto;gap:8px;align-items:center;padding:8px 0;border-top:1px solid var(--rf-line);font-size:13px}.prize-mini small{display:inline}.prize-editor{grid-column:1/-1}.filters{display:flex;flex-wrap:wrap;gap:8px;grid-column:1/-1}.filters>*{width:auto;min-width:120px}.ship-fields{display:flex!important;flex-direction:row!important;gap:6px!important}.ship-fields input{width:120px}.metric-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:1px;background:var(--rf-line)}.metric-grid article{display:flex;min-height:120px;padding:18px;flex-direction:column;gap:8px;background:var(--rf-bg)}.metric-grid span,.metric-grid small{color:var(--rf-muted);font-size:12px}.metric-grid strong{font-size:28px}.dashboard{padding:20px}.stats-table{margin-top:20px}.stats-head,.stats-row{display:grid;grid-template-columns:minmax(0,1fr) repeat(4,100px);gap:12px;align-items:center;padding:12px 0;border-bottom:1px solid var(--rf-line)}.stats-head{color:var(--rf-muted);font-size:12px}.stats-row span{font-size:13px}@media(max-width:900px){.workspace{grid-template-columns:1fr}.metric-grid{grid-template-columns:repeat(2,1fr)}.stats-head,.stats-row{grid-template-columns:minmax(0,1fr) repeat(2,80px)}.stats-head span:nth-child(n+4),.stats-row span:nth-child(n+4){display:none}}@media(max-width:600px){.form-grid{grid-template-columns:1fr}.form-grid .full{grid-column:auto}.metric-grid{grid-template-columns:1fr 1fr}.prize-mini{grid-template-columns:1fr auto}.prize-mini button{grid-column:2}.ship-fields{flex-wrap:wrap}.win-row{grid-template-columns:1fr auto}}
.music-review-main{display:flex!important;flex-direction:row!important;align-items:center;gap:10px}.music-review-main img{width:48px;height:48px;object-fit:cover;border-radius:6px;background:var(--rf-bg-subtle)}.music-review-actions{display:flex!important;flex-direction:row!important;gap:7px}.music-review-actions .danger{color:var(--rf-danger)}
</style>
